B('25血溅黄金柱',[
C('bloodshadow','血掌影','血掌影是争夺战时遗留文件的第三方组织首脑，真名、国籍和容貌都没有被可靠揭开。他的代号是一种自我宣传：别人只能感到杀戮的影子，无法知道施令者是谁。行动中，他让伪装艺术家的部下混入艺术院，以猴子走脱等闹剧转移视线；部下被擒后，又用通讯器重申纪律，迫使尚在犹豫的人服毒，使木兰花无法从活口取得线索。他懂得把调查者的失败转化为心理压力，电话中嘲笑搜身、提起北非寻金，还拿婚恋和退休刺激木兰花。后来他主动送回手杖，谎称已取走假钞，真正意图没有完全说清；穆秀珍跟踪送件车辆，却在黑暗车厢被他用强光和毒针威胁控制。他的神秘并非无敌：下车时转身的空隙，让穆秀珍扑上来、将他击昏并拖走。醒后他突袭脱身，向接应车奔去。撞车现场有两具尸体，但木兰花根据上车时间推测他逃走了，原文没有确认其死亡。终局保留隐藏身份、组织操控和狠毒手段，不赋予真正隐身、必中毒针或对所有下属的绝对精神支配。','在撞车前脱身；木兰花推断他未上接应车而逃走，未被捕或确认死亡。','真面目未见；以冷酷笑声、电话声音和强光后的轮廓出现。','取得隐秘财富，保护身份和组织，打击介入者的信心。','先在远处羞辱与操控，接近时依靠光线和毒针；失手后诈醒突袭。','秘密组织协调、通讯、毒针威胁及环境遮蔽；隐秘来自保密安排而非超能力。',[(1888,1912,'远程纪律迫自杀'),(1972,2006,'心理挑衅'),(2470,2506,'代号与动机'),(2528,2586,'被擒与突袭脱身'),(2690,2696,'结局仅推断逃走')],[('下属被对方动摇','仍能通过通讯传令','重申纪律，可能命其以死亡保密。'),('敌手暂时查无结果','掌握其在意的失败和关系','用嘲讽刺激情绪，诱其脱离判断。'),('必须在近距离转移俘虏','遮蔽优势即将短暂失效','仍倾向相信威慑，可能留下扑击空隙。')],roles=['反派'],scores=GUN,tier='并',uncertainties=['首脑的外貌、国家背景与真实姓名未明。','自称毒针百发百中不是经过验证的绝对命中能力。','末尾存活为木兰花的推论，不是现场目击。']),
C('goldpillar_consular_agent','追索手杖的领馆特务','这名高瘦的领事馆特务最先以强硬姿态出现在西蒙死亡的现场，用藏在大衣里的手枪迫使高翔放弃干预，让同伴搬走尸体。他以外交机构的地位掩护秘密工作，却漏掉死者携带的手杖，随后到木兰花家追索，企图在少说内情的情况下拿回文件。木兰花与穆秀珍先后以藏枪、打火机和精确射击压住他的行动，使他不得不退去。他没有因此放弃，而花钱雇惯窃入屋，结果反而让木兰花循约定的咖啡馆找到自己。再次面对枪口，他起初判断木兰花不会无缘无故杀人，仍试图维持镇定；当她声称总领事已经收到手杖，他担心自己失职，才讲出西蒙盗卖旧文件、两个情报贩子居间和贵族集团接洽的内情。他承认自己也研究过残缺资料，却不能解释宝物究竟是什么。终局他被解除武装后放行，没有证据表明属于血掌影组织。人物的对立来自情报保密和职务利益，不能把三起毒针杀人全算在他头上，也不能将领馆身份视为可跨越一切司法和人身限制的权力。','向木兰花交代文件来源与藏宝线索，被放行；后续行动未写。','高而瘦，穿大衣，面目阴森，说话带外国口音。','取回领馆外流文件，避免失职并维护本方秘密。','先以身份和枪械压人；担心上级追责时更可能披露信息。','特务监视、手枪、雇用窃贼和情报渠道；不掌握文件中全部秘密。',[(136,166,'武装取走尸体'),(334,438,'索杖与受制'),(1468,1478,'雇主辨认'),(1522,1626,'情报解释与被释放')],[('敏感人员在公共场合死亡','自己需要收回物证','以机构身份和武力争夺处置权。'),('正面索取失败','可用金钱找第三人','转用雇佣盗窃，但会留下交付地点。'),('上级可能已得到关键物件','自己隐瞒将显得失职','比面对空泛威胁更愿说出真实内情。')],roles=['阶段性对立者'],scores=GUN,tier='并'),
C('goldpillar_thief','受雇窃取手杖的惯窃','这名独来独往的惯窃长期靠技术避开警方，几件悬而未决的案件出自他手，警局甚至没有他的既有档案。他不问雇主身份，只接受报酬和指定物件，这一次被要求到木兰花家偷一根手杖，约定午夜前到蓝色池塘咖啡馆交货。潜伏被云四风发现后，他并非立即束手，而借预先挂好的绳索逃向围墙，用手枪压住追来的两人。穆秀珍连续射断绳索、以擦面子弹警告，再击飞他手中的枪，使惯用的退路逐一失效；他最后试图挥拳，却被云四风踢中、高翔扭住双臂。到了客厅，他承认职业和受雇经过，仍以不知道雇主为辩解，但描述了对方外貌、口音与交货地点。高翔随后录得多件旧案口供，原本没有留下的身份终于与案件联系起来。终局他已落网，没有原文支持后来脱逃。角色的本领在隐蔽行动、预设退路与枪械掩护；一次长期未被捕不等于完美潜行，向陌生雇主不过问来历的职业习惯，也恰使他承担了远超普通盗窃的危险。','被四人擒获并供述旧案，交付警方处理的后续结果未写。','瘦削，穿便于夜行的紧身运动衣，被捕后脸色苍白。','按报酬取得指定物件，失败时优先保命。','使用预备逃路和手枪反击，完全受制后供出可交换的信息。','夜行、盗窃、攀绳、手枪和现场退路安排；非隐身或完美反侦查。',[(1400,1436,'潜入、射击与被擒'),(1440,1476,'受雇条件和雇主描述'),(1488,1504,'口供和犯罪履历')],[('有人愿意付钱取物','自己不愿卷入背景','只问交货条件，可能低估目标危险。'),('潜入被发现','尚有预设绳索和枪械','边还击边撤离，而不主动久战。'),('退路和武器相继失去','对方已能控制身体','供出雇佣细节，求减轻当前风险。')],roles=['反派'],scores=GUN,tier='并'),
C('goldpillar_noble_envoy','贵族集团的绑架交涉人','贵族集团的交涉人到木兰花家传话，声称穆秀珍和云四风目前安好，但二十四小时内若没有交出手杖，处境便会改变。他自信背后有武装支援，面对高翔的拳头能伸手托住，再以口哨使窗外八柄机枪同时现身。这套压迫却立即被反转：高翔抓腕扭臂，将他挡在身前，枪手不敢开火，他反而成为令同伴缴械的命令来源。疼痛和恐惧使他讲出文斯酒店的交货房号，又交出歌芳伯爵的金属名片，以首领不愿杀人的信条担保人质安全。他同时强调逼不得已仍会杀人，所谓贵族体面并没有阻止绑架勒索。高翔试探用药审问时，他声称出任务前已注射反诚实液，接受另一种药会出现精神异常；这段只是他的陈述，不能变成已经验证的药物免疫。高翔考虑人质处境后放他与枪手离去，后来的接待人承认集团找错目标并释放人质。终局人物仍是有限知情的中间执行者，既不是歌芳伯爵本人，也没有证明掌握集团全部联络。','带部下离开交涉现场；集团后来承认误认目标并放人，本人后续未写。','成年男子，谈判从容；被扭臂后面色苍白、不断呻吟。','迫使高翔交出手杖，完成集团限定的交涉任务。','以武装包围提高要价，自己被反制后让步。','近身格挡、勒索交涉与八名实际枪手支援；枪手和命令链须在场。',[(840,896,'威胁、包围和被反制'),(904,974,'名片、组织说明和离去'),(1302,1310,'集团后来的道歉与放人')],[('人质在己方控制中','对方仍未交物','设期限并让后果保持模糊。'),('对方动手挑战','隐藏护卫已就位','用信号显示武力以恢复主动。'),('自己落入枪线成为人质','护卫开火会连同自己受害','服从降枪指令并改用谈判。')],roles=['反派'],scores=GUN,tier='并',uncertainties=['所谓预先注射反诚实液只由本人宣称，不能证明审讯免疫。']),
C('olatine','奥拉婷夫人','奥拉婷夫人是贵族集团安排在文斯酒店接收手杖的人，登记为来自巴西的贵妇。原文中的她有优雅风度，但真正关键的分工是擅长拆合复杂拼构：目标手杖由多部分巧妙相合，即使是她，也需要一定时间才能打开检查。集团将这一专长嵌入绑架交易，要求收到真物后以连续开关灯光通知外面的监视者。她后来被木兰花控制，以床单捆在衣橱中，口中塞布；木兰花取得灯光信号的知识，化装成她接待高翔。酒店场面中嘲笑假手杖、识破高翔、接电话放人的精彩应对，实际都属于木兰花，不能当作她本人的智谋战绩。真正的夫人只能发出愤怒声音，盼同伴发现迟迟不交货而来救她。接待人后来解释，过早发出信号恰好暴露了冒充，因为真正的专家不可能那么快完成检查。终局没有写她的审判或具体获救过程，木兰花只是预计监视者会来。角色以技术分工与贵族外观参与胁迫，却不是凭优雅仪态便可完全识破伪装的人；她的专长应在实际物件和时间条件下发挥。','被木兰花捆绑留在酒店衣橱；预期同伴会救，实际获救过程未写。','四五十岁贵妇，风度佳；华贵睡袍属于被冒充的衣着外观。','依集团安排检查和接收手杖，完成交易岗位的任务。','受制时愤怒挣扎；专业能力依赖能接触实物并有时间。','复杂机械式拼构的拆合专长及灯光联络知识；不转移木兰花冒充时的能力。',[(1014,1034,'登记身份与外观'),(1140,1148,'本人被绑与信号'),(1334,1340,'专业分工和假扮破绽')],[('收到结构复杂的物件','需要确认内部文件','按部件拆解检查，不只凭外形宣布真伪。'),('检查尚未完成','同伴等候放人信号','专业所需时间构成不能省略的条件。'),('被别人冒用身份','身体受到拘束无法讲话','会愤怒反抗，但不能凭意志取消已发出的信号。')],roles=['阶段性对立者'],aliases=['奥拉婷（真身）'],uncertainties=['登记姓名和巴西来历是否真实未确认。','高翔在酒店遇到的多数言行出自木兰花假扮，不计本人能力。']),
C('goldpillar_noble_host','贵族集团的晚宴接待人','这名五十岁上下的高个男子在洋房接待被武装人员带来的木兰花，先命人收枪，再以晚宴、礼节和赞美恢复客人的体面。木兰花猜他就是歌芳伯爵，他明确否认，却不肯报自己的姓名；故事没有后来揭晓，因此他与传说中的首领须保持身份距离。他并非单纯炫耀胜利，而是承认集团误以为手杖还在木兰花手里，绑架和破坏都找错了对象，愿赔偿并允许她打电话核验同伴已经自由。他从放人信号发得过早判断酒店接待者是冒充，也由此认为木兰花没有真正拆过手杖，转而寻求她提供物件失窃的经过。这个判断既显示对具体流程的熟悉，也受当时有限信息支撑。对于文件内容，他仍守住边界，只讲集团谋财、不愿别人受损的宗旨和过去盗取秘密存款的例子，没有完全满足木兰花的追问。终局晚宴结束后他不再介入明面冲突。人物的礼貌与道歉有实际让步，却不能抹去集团先前的绑架，更不能把自称不损人财产当成普遍成立的伦理判断。','向木兰花道歉、放人并取得失杖经过，真实姓名与后续去向未写。','身形很高，约五十岁，穿晚服，举止和屋内布置讲究。','维护集团利益和体面，发现找错目标后减少无谓敌意。','先借礼节缓和武装强请造成的敌意，再有选择地交换信息。','流程核验、谈判、赔偿承诺和集团人手；不证明个人格斗或神秘首领身份。',[(1264,1290,'外观、否认伯爵身份'),(1298,1346,'道歉、放人和推理'),(1352,1382,'保密与利益逻辑')],[('事实表明集团找错对象','继续威胁只会增加损失','承认具体错误并提供可核验的补救。'),('交付步骤的时长异常','自己熟悉专业检查流程','从细节识别冒充和信息缺口。'),('客人追问核心利益','友好关系已足以继续交涉','保持礼貌，但仍限制披露范围。')],roles=['阶段性对立者'],scores={'physical':1,'energy':0,'scope':1,'sustain':1,'range':1,'combat':1},tier='纸',uncertainties=['木兰花怀疑其为歌芳伯爵，但本人否认，原文未确证。']),
C('goldpillar_monkey_painter','牵猴画家的毒针杀手','这名杀手以牵着猴子作画的艺术家身份混入艺术院，利用普通展览者的外观躲在多方争夺文件的现场。猴子走脱的混乱与西蒙死亡同时发生，木兰花后来据此把他和伞骨雕塑者联成同一组织的掩护行动，而不是将这些闹剧当作巧合。他在咖啡馆外的小巷接近木兰花，发射细小毒针；木兰花提前侧身侥幸避开，随即装作中针倒下。杀手以为偷袭成功，走近提起她并摸向脸部，意图收回针，反给对方近身反击的机会，腹部和后脑连续受击而昏。他被带回住所，醒来面对劝供并没有交代身份，突然服毒死亡。毒物预先藏在口中的解释来自现场情形，具体装置没有描写；不能把这次自杀扩大为随时逃出一切拘禁的能力。终局回溯保留一个接受严密组织控制、愿以死保密的执行者，也保留误信命中、必须近前回收凶器的弱点。他不是血掌影本人，三起谋杀是否全部由他亲手施针，原文并未逐件现场证明。','被木兰花擒获，醒来后服毒自杀。','以牵猴作画的艺术家形象活动；实际姓名与背景未明。','执行组织的袭杀与保密任务，避免落入口供链。','隐蔽发针；认定得手便近前收物，被擒后以死亡拒供。','艺术家伪装、毒针偷袭和现场掩护；针须实际命中，普通身体可被击昏。',[(1652,1688,'毒针袭击、假死反制与身份'),(1688,1690,'闹剧掩护判断'),(1764,1802,'被擒、自杀与组织约束')],[('目标从狭巷旁经过','可缩短射击距离','借偶遇外观发动毒针袭击。'),('目标表现为已经中毒','未再次核验反抗力','靠近回收凶器，可能被假死反制。'),('醒来发现自己被拘束','组织保密纪律高于自身生存','可能拒供并使用预藏毒物。')],roles=['反派'],scores=GUN,tier='并',revive=True,uncertainties=['三名早期死者均中毒针，但不能逐一确认全由此人亲手杀害。']),
C('goldpillar_umbrella_sculptor','伞骨雕塑者','伞骨雕塑者在艺术院把伞骨堆成作品，和牵猴画家一起制造过吸引视线的场面。他的艺术身份为组织观察和行动提供常驻掩护，但本人姓名与实际艺术经验没有交代。木兰花第二次到来时，他面色苍白，用异样眼光盯着她，显然知道同伴的处境；面对关于口中毒药的提醒，他惊慌后退，撞散了自己的雕塑。木兰花说已经掌握资料、并不需要他作供，试图减轻他必须殉组织的负担，他苦笑、犹豫，没有立即自杀，说明他并非没有求生意愿。转折发生在怀中的袋表式通讯器响起之后：声音重申组织纪律第一条，他反复念着，最终服毒倒下。木兰花来不及阻止，也没能通过周围人的搜身找到施令者。终局他已死，若恢复行动须明示回溯；他能理解威胁、恐惧和劝说，却没有证据表明受到超自然心控。角色的戏剧性在短暂出现的生路被等级压力压回去，新的场面应允许具体的保护条件改变他的选择，而不是把一句口令写成任何时候都不可抵抗的死亡法则。','在组织通过通讯器提醒纪律后服毒死亡。','伪装雕塑者，面对木兰花时脸色苍白、神态不安。','服从组织并保守秘密，同时存在明显求生犹豫。','被问破身份会慌乱；减轻责任的劝说有效，但上级声音使其重新恐惧。','展览场所伪装与袋表式通讯；未展示独立战斗能力。',[(1866,1896,'身份、恐惧与劝说'),(1896,1912,'通讯命令和死亡'),(1920,1964,'施令者未被找到')],[('身份似已被识破','对方又明确表示无需口供','会犹豫是否仍有保命余地。'),('上级即时介入','保密纪律重新成为焦点','可能以服毒回应压力。'),('失去可以保证安全的退路','自己相信组织无处不在','倾向高估追罚威胁；实际安全保障可成为新的选择入口。')],roles=['反派'],revive=True)
],cast=['mu_lanhua','mu_xiuzhen','gao_xiang','yun_sifeng','fang_director'],excluded=[{'name':'郭尔准、西蒙、果德','reason':'是文件流转与命案背景中的死者；未以在场主要对立行动展开，其盗卖和中介经历作为案情保留，不扩成独立战斗角色。'},{'name':'歌芳伯爵','reason':'仅作为神秘集团首领被提及；晚宴接待人明确否认就是他，证据不足合并或另立实际出场卡。'},{'name':'费利准将、总领事、雷贝、谭院长','reason':'一次性职务阻碍或协助角色，未构成独立主线对抗与跨书角色。'},{'name':'车祸司机、接应枪手及其他无名监视者','reason':'仅作所属组织当场执行者，无独立身份和目标。'}],notes=['血掌影在末尾被推测逃走，不能把两具车祸尸体之一直接认作他。','酒店中多数奥拉婷夫人的言行实际是木兰花假扮。','宝藏为被覆盖的名画，终局恢复展出，不作为任何人的私人财产或战斗武器。'])
